python3 -c "
import ast, importlib
for modname, pyi in [('more_itertools.more','more_itertools/more.pyi'),('more_itertools.recipes','more_itertools/recipes.pyi')]:
    mod = importlib.import_module(modname)
    tree = ast.parse(open(pyi).read())
    stub = {n.name for n in tree.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef))}
    stub |= {t.id for n in tree.body if isinstance(n,ast.Assign) for t in n.targets if isinstance(t,ast.Name)}
    stub |= {n.target.id for n in tree.body if isinstance(n,ast.AnnAssign) and isinstance(n.target,ast.Name)}
    run = {k for k in dir(mod) if not k.startswith('_') and getattr(getattr(mod,k),'__module__',modname) == modname}
    print(modname, 'in runtime, not stub:', sorted(run-stub)[:30])
    print(modname, 'in stub, not runtime:', sorted(stub-run)[:30])
"; cat more_itertools/more.pyi | head -30

